export declare function mergeMapBounded<T, R>(project: (value: T) => ObservableInput<R>, concurrent: number, onBacklog?: (isBacklogged: boolean) => void, maxWaiting?: number, onOverflow?: () => void): OperatorFunction<T, R>;
